import torch
import triton
import triton.language as tl

_TORCH_TO_TL = {
    torch.float16: tl.float16,
    torch.bfloat16: tl.bfloat16,
    torch.float32: tl.float32,
    torch.int8: tl.int8,
    torch.int16: tl.int16,
    torch.int32: tl.int32,
    torch.int64: tl.int64,
    torch.uint8: tl.uint8,
    torch.bool: tl.int1,
}


def _identity_for(dtype):
    if dtype.is_floating_point:
        return float("inf")
    return int(torch.iinfo(dtype).max)


def _next_pow2(x):
    return 1 << (max(1, int(x)) - 1).bit_length()


def _normalize_dim(dim, ndim):
    if dim is None:
        return list(range(ndim))
    if isinstance(dim, int):
        dim = [dim]
    else:
        dim = list(dim)
    out = []
    for d in dim:
        d = int(d)
        if d < 0:
            d += ndim
        out.append(d)
    return sorted(set(out))


def _target_programs(inp):
    try:
        from triton.runtime import driver

        idx = inp.device.index
        if idx is None:
            idx = 0
        props = driver.active.utils.get_device_properties(idx)
        n = None
        if isinstance(props, dict):
            n = props.get("num_vectorcore") or props.get("num_aicore")
        else:
            n = getattr(props, "num_vectorcore", None) or getattr(
                props, "num_aicore", None
            )
        if n:
            return int(n) * 4
    except Exception:
        pass
    return 64


@triton.jit
def amin_orii_kernel(
    inp_ptr,
    out_ptr,
    O,
    R,
    I,
    identity,
    BLOCK_I: tl.constexpr,
    BLOCK_R: tl.constexpr,
    DTYPE: tl.constexpr,
    CDTYPE: tl.constexpr,
):
    # Contiguous layout: element (o, r, i) at o*R*I + r*I + i.
    # One program owns one outer index o and a tile of I (inner) lanes,
    # looping the reduction axis R. Loads along i are stride-1 (coalesced).
    pid = tl.program_id(0)
    o = pid // tl.cdiv(I, BLOCK_I)
    ib = pid % tl.cdiv(I, BLOCK_I)
    i = ib * BLOCK_I + tl.arange(0, BLOCK_I)
    i_mask = i < I
    base = o * R * I
    acc = tl.full((BLOCK_I,), identity, dtype=CDTYPE)
    for r0 in range(0, R, BLOCK_R):
        r = r0 + tl.arange(0, BLOCK_R)
        r_mask = r < R
        offs = base + r[:, None] * I + i[None, :]
        m = r_mask[:, None] & i_mask[None, :]
        v = tl.load(inp_ptr + offs, mask=m, other=identity)
        acc = tl.minimum(acc, tl.min(v, axis=0).to(CDTYPE))
    out_off = o * I + i
    tl.store(out_ptr + out_off, acc.to(DTYPE), mask=i_mask)


@triton.jit
def amin_split_kernel(
    inp_ptr,
    partial_ptr,
    O,
    R,
    I,
    NSPLIT,
    identity,
    BLOCK_I: tl.constexpr,
    BLOCK_R: tl.constexpr,
    DTYPE: tl.constexpr,
    CDTYPE: tl.constexpr,
):
    # Stage 1 of split reduction: grid = (O * cdiv(I,BLOCK_I), NSPLIT).
    # Split program s reduces its slice of R into partial[o, s, i].
    pid = tl.program_id(0)
    s = tl.program_id(1)
    ncols = tl.cdiv(I, BLOCK_I)
    o = pid // ncols
    ib = pid % ncols
    i = ib * BLOCK_I + tl.arange(0, BLOCK_I)
    i_mask = i < I
    base = o * R * I
    # even split of R across NSPLIT programs
    chunk = tl.cdiv(R, NSPLIT)
    r_start = s * chunk
    r_end = tl.minimum(r_start + chunk, R)
    acc = tl.full((BLOCK_I,), identity, dtype=CDTYPE)
    for r0 in range(r_start, r_end, BLOCK_R):
        r = r0 + tl.arange(0, BLOCK_R)
        r_mask = r < r_end
        offs = base + r[:, None] * I + i[None, :]
        m = r_mask[:, None] & i_mask[None, :]
        v = tl.load(inp_ptr + offs, mask=m, other=identity).to(CDTYPE)
        acc = tl.minimum(acc, tl.min(v, axis=0))
    # partial layout: [O, NSPLIT, I]
    poff = (o * NSPLIT + s) * I + i
    tl.store(partial_ptr + poff, acc.to(DTYPE), mask=i_mask)


@triton.jit
def amin_stage2_kernel(
    partial_ptr,
    out_ptr,
    O,
    NSPLIT,
    I,
    identity,
    BLOCK_I: tl.constexpr,
    BLOCK_S: tl.constexpr,
    DTYPE: tl.constexpr,
    CDTYPE: tl.constexpr,
):
    pid = tl.program_id(0)
    ncols = tl.cdiv(I, BLOCK_I)
    o = pid // ncols
    ib = pid % ncols
    i = ib * BLOCK_I + tl.arange(0, BLOCK_I)
    i_mask = i < I
    base = o * NSPLIT * I
    acc = tl.full((BLOCK_I,), identity, dtype=CDTYPE)
    for s0 in range(0, NSPLIT, BLOCK_S):
        s = s0 + tl.arange(0, BLOCK_S)
        s_mask = s < NSPLIT
        offs = base + s[:, None] * I + i[None, :]
        m = s_mask[:, None] & i_mask[None, :]
        v = tl.load(partial_ptr + offs, mask=m, other=identity).to(CDTYPE)
        acc = tl.minimum(acc, tl.min(v, axis=0))
    out_off = o * I + i
    tl.store(out_ptr + out_off, acc.to(DTYPE), mask=i_mask)


@triton.jit
def amin_inner_kernel(
    inp_ptr,
    out_ptr,
    O,
    R,
    identity,
    BLOCK_M: tl.constexpr,
    BLOCK_R: tl.constexpr,
    DTYPE: tl.constexpr,
    CDTYPE: tl.constexpr,
):
    # Innermost-axis reduction (I==1): element (o, r) at o*R + r.
    # One program owns BLOCK_M outer rows, loops R with wide [BLOCK_M, BLOCK_R]
    # tiles so each row's reduced axis is stride-1 (fully coalesced), reduce ax 1.
    pid = tl.program_id(0)
    m = pid * BLOCK_M + tl.arange(0, BLOCK_M)
    m_mask = m < O
    acc = tl.full((BLOCK_M,), identity, dtype=CDTYPE)
    for r0 in range(0, R, BLOCK_R):
        r = r0 + tl.arange(0, BLOCK_R)
        r_mask = r < R
        offs = m[:, None] * R + r[None, :]
        mm = m_mask[:, None] & r_mask[None, :]
        v = tl.load(inp_ptr + offs, mask=mm, other=identity)
        acc = tl.minimum(acc, tl.min(v, axis=1).to(CDTYPE))
    tl.store(out_ptr + m, acc.to(DTYPE), mask=m_mask)


